CREATE TABLE `community_polls` (
  `id` text PRIMARY KEY NOT NULL,
  `site_id` text NOT NULL,
  `channel_id` text NOT NULL,
  `created_by` text NOT NULL,
  `question` text NOT NULL,
  `options` text NOT NULL DEFAULT '[]',
  `expires_at` text,
  `created_at` text DEFAULT (CURRENT_TIMESTAMP),
  FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`),
  FOREIGN KEY (`channel_id`) REFERENCES `community_channels`(`id`),
  FOREIGN KEY (`created_by`) REFERENCES `users`(`id`)
);
CREATE TABLE `community_poll_votes` (
  `id` text PRIMARY KEY NOT NULL,
  `poll_id` text NOT NULL,
  `user_id` text NOT NULL,
  `option_index` integer NOT NULL,
  `created_at` text DEFAULT (CURRENT_TIMESTAMP),
  FOREIGN KEY (`poll_id`) REFERENCES `community_polls`(`id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`)
);
CREATE TABLE `community_messages` (
  `id` text PRIMARY KEY NOT NULL,
  `site_id` text NOT NULL,
  `channel_id` text NOT NULL,
  `user_id` text NOT NULL,
  `content` text NOT NULL,
  `image_url` text,
  `is_pinned` integer NOT NULL DEFAULT 0,
  `poll_id` text,
  `created_at` text DEFAULT (CURRENT_TIMESTAMP),
  FOREIGN KEY (`site_id`) REFERENCES `sites`(`id`),
  FOREIGN KEY (`channel_id`) REFERENCES `community_channels`(`id`),
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`),
  FOREIGN KEY (`poll_id`) REFERENCES `community_polls`(`id`)
);
CREATE UNIQUE INDEX `users_email_or_phone_unique` ON `users` (`email_or_phone`);
CREATE INDEX `idx_push_subscriptions_user` ON `push_subscriptions` (`user_id`);
CREATE INDEX `idx_push_subscriptions_endpoint` ON `push_subscriptions` (`endpoint`);
CREATE INDEX `idx_password_reset_tokens_user` ON `password_reset_tokens` (`user_id`);
CREATE INDEX `idx_platform_public_contact_status` ON `platform_public_contact` (`status`);
CREATE INDEX `idx_platform_public_contact_created` ON `platform_public_contact` (`created_at`);
CREATE INDEX `idx_admin_support_site` ON `admin_support_tickets` (`site_id`);
CREATE INDEX `idx_admin_support_status` ON `admin_support_tickets` (`status`);
CREATE INDEX `idx_notifications_user_unread` ON `notifications` (`user_id`, `read_at`);
CREATE INDEX `idx_notifications_created` ON `notifications` (`created_at`);
CREATE INDEX `idx_transactions_site_date` ON `transactions` (`site_id`, `date`);
CREATE INDEX `idx_community_channels_site` ON `community_channels` (`site_id`);
CREATE INDEX `idx_community_polls_channel` ON `community_polls` (`channel_id`);
CREATE UNIQUE INDEX `idx_community_poll_vote_unique` ON `community_poll_votes` (`poll_id`, `user_id`);
CREATE INDEX `idx_community_messages_channel_date` ON `community_messages` (`channel_id`, `created_at`);
